INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(16783, 'koKR', 'Rób, co mówię! Leć!', 'Rób, co mówię! Leć!', 0),
(16784, 'koKR', 'Chronić Botanikę za wszelką cenę!', '', 0),
(16785, 'koKR', 'Wszyscy intruzi muszą zostać wyeliminowani!', '', 0),
(16942, 'koKR', 'Najwyższy Botaniku?', 'Najwyższy Botaniku?', 0),
(16945, 'koKR', '...mamrocze...Płatki ognia...mamrocze...', '', 0),
(16946, 'koKR', '...mamrocze, mamrocze...', '', 0),
(16947, 'koKR', '...ciernie pnącza...mamrocze...au!', '', 0),
(16948, 'koKR', '...przy odpowiedniej mieszance, może...', '', 0),
(16961, 'koKR', 'Witajcie, bracia! Napawajcie się chwałą mojej mocy!', '', 0),
(16993, 'koKR', 'Uciekajcie stąd, jest ich za dużo! Uciekajcie, póki możecie!', 'Uciekajcie stąd, jest ich za dużo! Uciekajcie, póki możecie!', 0),
(16994, 'koKR', 'Pomocy! Niech ktoś nam pomoże!', 'Pomocy! Niech ktoś nam pomoże!', 0),
(16999, 'koKR', '', 'Tak. To zadziałało.', 0),
(17000, 'koKR', '', 'Hmm...', 0),
(17178, 'koKR', 'Hmm... Obrona przed mrozem, ogniem i tajemną mocą reaguje szybciej niż w partii 7, ale obrona przed naturą pozostaje bierna.', 'Hmm... Obrona przed mrozem, ogniem i tajemną mocą reaguje szybciej niż w partii 7, ale obrona przed naturą pozostaje bierna.', 0),
(17562, 'koKR', '', '%s wzywa posiłki!', 0),
(17624, 'koKR', 'Zabić $n!', 'Zabić $n!', 0),
(18376, 'koKR', 'Dzieci, do mnie!', 'Dzieci, do mnie!', 0),
(19936, 'koKR', '', 'Podejdźcie. Dopilnuję, by was należycie powitano!', 0),
(19937, 'koKR', '', 'Och, przestań skomleć!', 0),
(19938, 'koKR', '', 'Misja wykonana!', 0),
(19939, 'koKR', '', 'Nie masz już do czynienia z byle podwładnym!', 0),
(19940, 'koKR', '', 'Band\'or shorel\'aran!', 0),
(19941, 'koKR', '', 'Straże, do mnie! Wyrżnąć tych najeźdźców!', 0),
(19942, 'koKR', '', 'Jeszcze nawet... nie zaczęłam...', 0),
(19944, 'koKR', 'Co wy wyprawiacie? Te okazy są bardzo delikatne!', '', 0),
(19945, 'koKR', 'Twój cykl życiowy właśnie się zakończył.', '', 0),
(19946, 'koKR', 'Nakarmisz robaki.', '', 0),
(19947, 'koKR', 'Endorel anuminor!', '', 0),
(19948, 'koKR', 'Natura ugina się przed moją wolą...', '', 0),
(19949, 'koKR', 'Okazy... trzeba ocalić.', '', 0),
(20012, 'koKR', 'Co to za utrapienie? Zginiecie!', '', 0),
(20013, 'koKR', 'Szukacie nagrody, co? A może być śmierć?', '', 0),
(20014, 'koKR', 'Nie lubię mówić „a nie mówiłem”...', '', 0),
(20015, 'koKR', 'Twoje życie będzie moje!', '', 0),
(20016, 'koKR', 'Rozkoszuję się waszym bólem!', '', 0),
(20017, 'koKR', 'Spopielę was!', '', 0),
(20018, 'koKR', 'Krzyczcie, płonąc!', '', 0),
(20019, 'koKR', 'Daleko... nie zajdziecie.', '', 0),
(20022, 'koKR', 'Może to nie jest... Nie, walczymy! Pomóżcie mi!', 'Może to nie jest... Nie, walczymy! Pomóżcie mi!', 0),
(20024, 'koKR', 'Kto zakłóca spokój tego sanktuarium?', 'Kto zakłóca spokój tego sanktuarium?', 0),
(20025, 'koKR', 'Musicie zginąć! Ale chwila: to nie... Nie, nie... musicie zginąć!', 'Musicie zginąć! Ale chwila: to nie... Nie, nie... musicie zginąć!', 0),
(20026, 'koKR', 'Co ja robię? Dlaczego ja...', 'Co ja robię? Dlaczego ja...', 0),
(20028, 'koKR', 'Tak... zagubiony. Nie... należę tutaj.', 'Tak... zagubiony. Nie... należę tutaj.', 0);
